// ── helpers de mezcla ─────────────────────────────────────────────────────────────────────────
const _lerp  = (a, b, t) => a + (b - a) * t;
const _lerpC = (a, b, t) => [_lerp(a[0], b[0], t), _lerp(a[1], b[1], t), _lerp(a[2], b[2], t)];
const _extraeCieloMedio = (c) => Array.isArray(c) ? c.slice() : (c && c.medio ? c.medio.slice() : [0.35, 0.65, 0.95]);
const _niebla = (n) => n ? [n.near, n.far, n.tinte] : [260, 520, 0];

// Aplica un preset de golpe, sin transición.
function _aplicaYa(e) {
  if(e.cielo && typeof e.cielo === 'object' && !Array.isArray(e.cielo)) game.cielo(e.cielo);
  else game.cieloColor(e.cielo);
  game.niebla(e.niebla || false);
  game.luz(e.luz != null ? e.luz : 1);
  game.reflejoAgua(e.reflejo);
  game.vistaAgua(e.agua);
  game.sunShade = e.sombra;
}

// Lee el estado actual, para poder transicionar DESDE él.
function _estadoActual() {
  const c = game.cielo();
  const r = game.reflejoAgua();
  const a = game.vistaAgua();
  const n = game.niebla();
  return {
    cielo:  c,
    cieloMedio: c.medio.slice(),
    niebla: _niebla(n),
    fuerza: r.fuerza, curva: r.curva, opacidad: r.opacidad,
    aguaSky: (a.sky || [0.1, 0.34, 0.6]).slice(), tinte: a.tinte,
    luz: (typeof game.luz === 'function') ? game.luz() : 1,
    sombra: (typeof game.sunShade === 'number') ? game.sunShade : 0.55
  };
}

game.entorno = function (nombre, opts) {
  if (nombre == null) { console.log('Ambientes: ' + Object.keys(Entornos).join(', ')); return Object.keys(Entornos); }
  const e = Entornos[String(nombre).toUpperCase()];
  if (!e) { console.warn('game.entorno: no existe «' + nombre + '». Hay: ' + Object.keys(Entornos).join(', ')); return; }

  if (mc._entornoRAF) { cancelAnimationFrame(mc._entornoRAF); mc._entornoRAF = 0; }

  const seg = (typeof opts === 'number') ? opts : (opts && +opts.segundos) || 0;
  if (!(seg > 0)) { _aplicaYa(e); mc._entornoActual = String(nombre).toUpperCase(); console.log('[ambiente] ' + mc._entornoActual); return e; }

  const de = _estadoActual();
  const a  = e.agua || {};
  const aB = { sky: (a.sky || de.aguaSky), tinte: (a.tinte != null ? a.tinte : de.tinte) };
  const rB = e.reflejo;
  const nB = _niebla(e.niebla);
  const cMedioB = _extraeCieloMedio(e.cielo);
  const t0 = performance.now();
  const paso = () => {
    const t = Math.min(1, (performance.now() - t0) / (seg * 1000));
    const k = t * t * (3 - 2 * t);
    if (e.cielo && typeof e.cielo === 'object' && !Array.isArray(e.cielo)) {
      game.cielo({
        horizonte: _lerpC(de.cielo.horizonte, e.cielo.horizonte, k),
        medio:     _lerpC(de.cielo.medio, e.cielo.medio, k),
        cenit:     _lerpC(de.cielo.cenit, e.cielo.cenit, k),
        suelo:     _lerpC(de.cielo.suelo, e.cielo.suelo, k)
      });
    } else {
      game.cieloColor(_lerpC(de.cieloMedio, cMedioB, k));
    }
    game.niebla({ near: _lerp(de.niebla[0], nB[0], k), far: _lerp(de.niebla[1], nB[1], k), tinte: _lerp(de.niebla[2], nB[2], k) });
    game.luz(_lerp(de.luz, (e.luz != null ? e.luz : 1), k));
    game.reflejoAgua({ fuerza: _lerp(de.fuerza, rB.fuerza, k), curva: _lerp(de.curva, rB.curva, k), opacidad: _lerp(de.opacidad, rB.opacidad, k) });
    game.vistaAgua({ sky: _lerpC(de.aguaSky, aB.sky, k), tinte: _lerp(de.tinte, aB.tinte, k), sigueCielo: false });
    game.sunShade = _lerp(de.sombra, e.sombra, k);
    if (t < 1) { mc._entornoRAF = requestAnimationFrame(paso); }
    else { mc._entornoRAF = 0; _aplicaYa(e); mc._entornoActual = String(nombre).toUpperCase(); console.log('[ambiente] ' + mc._entornoActual); }
  };
  paso();
  return e;
};

